/**
 * Calculate subtotal and total for an invoice (in cents).
 * @param {{ lines: Array<{ qty: number, unitPrice: number }> }}
 * @returns {{ subtotal: number, total: number }}
 */
export function invoiceTotals(invoice) {
  let subtotal = 0;
  for (const line of invoice.lines) {
    subtotal += lineTotal(line);
  }
  return {
    subtotal,
    total: subtotal,
  };
}

/**
 * Add or increase a line on a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number }> }} invoice
 * @param {{ sku: string, qty: number }}
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  const productResult = getProduct(sku);
  if (!productResult.ok) return fail('UNKNOWN_SKU');

  const existingLineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  const newLines = invoice.lines.map((l) => ({ ...l }));

  if (existingLineIndex >= 0) {
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    const product = productResult.value;
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((_, i) => i !== lineIndex);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

